import type { StoryBeat } from "@/lib/domain/story-world";
import type { RamayanaBeginningPlayableScene } from "./ramayana-beginnings-playable";

const beat = (
  id: string,
  title: { en: string; hi: string },
  narration: { en: string; hi: string },
  visualCue: string,
  characterIds: string[],
): StoryBeat => ({ id, title, narration, visualCue, characterIds });

const scene = (
  id: string,
  nodeIds: string[],
  decisiveChange: { en: string; hi: string },
  beats: StoryBeat[],
): RamayanaBeginningPlayableScene => ({ id, nodeIds, moment: { id, decisiveChange, beats } });

export const RAMAYANA_RAVANA_FINAL_BATTLE_PLAYABLE_SCENES: RamayanaBeginningPlayableScene[] = [
  scene("a-sons-death-puts-sita-in-danger", ["ravana", "indrajit", "sita", "suparshva", "lanka-counsellors", "lanka-families", "ravanas-court", "ashoka-grove", "sword", "grief-to-violence"], { en: "Ravana's grief for Indrajit becomes an immediate threat to Sita until one counsellor interrupts the rush toward irreversible violence.", hi: "इंद्रजीत का शोक रावण के भीतर सीता के लिए तत्काल खतरा बनता है, जब तक एक मंत्री अपरिवर्तनीय हिंसा की दौड़ रोकता नहीं।" }, [
    beat("the-news-makes-a-father-collapse", { en: "The news makes a father collapse", hi: "समाचार पिता को गिरा देता है" }, { en: "Counsellors tell Ravana that Lakshmana, aided by Vibhishana, has killed Indrajit. Ravana loses consciousness, wakes, and mourns the son who should have outlived him, naming Indrajit's mother, wife, inheritance, and unfinished family duties. The feared commander is also held in view as a son whose absence has entered several lives at once.", hi: "मंत्री रावण को बताते हैं कि विभीषण की सहायता से लक्ष्मण ने इंद्रजीत को मार दिया। रावण मूर्छित होकर उठता और उस पुत्र के लिए रोता है जिसे उससे अधिक जीना था; वह इंद्रजीत की माता, पत्नी, उत्तराधिकार और अधूरे पारिवारिक कर्तव्य गिनाता है। भयभीत करने वाला सेनानायक साथ ही ऐसा पुत्र दिखता है जिसकी अनुपस्थिति कई जीवनों में एक साथ पहुँची है।" }, "Collapse the command map into an intimate family constellation before any anger route lights up toward the grove.", ["ravana", "indrajit", "indrajits-mother", "indrajits-wife", "lanka-counsellors"]),
    beat("grief-turns-toward-the-captive", { en: "Grief turns toward the captive", hi: "शोक बंदी की ओर मुड़ता है" }, { en: "Ravana's sorrow converts into fury without changing the decision that caused the war. Remembering Indrajit's false image of Sita, he decides to make the threatened killing real and takes up a sword. The movement transfers the cost of a son's death onto a captive woman who did not choose the abduction, the siege, or the battlefield losses.", hi: "रावण का शोक उस निर्णय को बदले बिना क्रोध में बदलता है जिसने युद्ध पैदा किया। इंद्रजीत द्वारा बनाई सीता की झूठी छवि याद करके वह धमकी को सच करने का निश्चय करता और तलवार उठाता है। यह कदम पुत्र की मृत्यु का भार उस बंदी स्त्री पर डालता है जिसने न अपहरण चुना, न घेरा और न युद्ध की हानियाँ।" }, "Draw a dangerous red route from the court to the Ashoka grove while leaving the return-and-release route visibly available.", ["ravana", "indrajit", "sita", "sword", "ashoka-grove"]),
    beat("sita-must-interpret-danger-from-captivity", { en: "Sita must interpret danger from captivity", hi: "सीता को कैद से ही खतरा समझना पड़ता है" }, { en: "Seeing Ravana approach with a blade, Sita cannot know whether Rama and Lakshmana have died, whether the city's uproar marked victory, or whether her refusal has provoked her execution. She regrets declining Hanuman's escape offer and imagines the grief that might reach Kausalya. Captivity denies her reliable information even when her own life is the immediate stake.", hi: "रावण को तलवार के साथ आते देखकर सीता नहीं जान सकतीं कि राम-लक्ष्मण मारे गए, नगर का शोर विजय था या उनके इनकार ने हत्या भड़का दी। वे हनुमान के साथ न जाने पर पछतातीं और कौशल्या तक पहुँचने वाले शोक की कल्पना करती हैं। जब उनका जीवन तत्काल दाँव पर है, तब भी कैद उन्हें भरोसेमंद जानकारी से वंचित रखती है।" }, "Keep several unanswered explanations around Sita rather than revealing battlefield knowledge she cannot possess.", ["sita", "ravana", "rama", "lakshmana", "hanuman", "kausalya"]),
    beat("suparshva-stops-the-sword-not-the-war", { en: "Suparshva stops the sword, not the war", hi: "सुपार्श्व तलवार रोकता है, युद्ध नहीं" }, { en: "Suparshva confronts Ravana with the contradiction between his learning and the plan to kill a woman held under his power. He persuades the king to direct the promised violence toward Rama instead, and Ravana returns to court. Sita survives the moment, but release and restitution remain refused, so interruption prevents one atrocity without resolving the governing harm.", hi: "सुपार्श्व रावण के ज्ञान और उसके अधिकार में बंद स्त्री की हत्या की योजना के बीच विरोध सामने रखता है। वह राजा को प्रतिज्ञात हिंसा राम की ओर मोड़ने को मनाता है और रावण सभा लौटता है। सीता उस क्षण बचती हैं, पर मुक्ति और वापसी अब भी अस्वीकार हैं; रोक एक अत्याचार टालती है, मूल शासनकारी हानि नहीं सुलझाती।" }, "Close the sword path at Suparshva, but keep Sita's captivity and the battlefield route unresolved on the same map.", ["suparshva", "ravana", "sita", "lanka-counsellors", "ashoka-grove"]),
  ]),
  scene("an-army-is-sent-to-soften-rama", ["ravana", "rama", "sugriva", "vibhishana", "hanuman", "jambavan", "allied-fighters", "lanka-fighters", "gandharva-weapon", "lanka-gates"], { en: "Ravana spends another army to weaken Rama, but a weapon that distorts perception destroys cohesion and sends the survivors home.", hi: "रावण राम को कमजोर करने के लिए एक और सेना झोंकता है, पर अनुभूति बिगाड़ने वाला अस्त्र संगठन तोड़कर बचे लोगों को घर भेज देता है।" }, [
    beat("ravana-promises-a-wounded-target", { en: "Ravana promises a wounded target", hi: "रावण घायल लक्ष्य का वादा करता है" }, { en: "Back in court, Ravana orders every available elephant, horse, vehicle, and fighter into battle. His instruction is to surround Rama and wound him before Ravana arrives the next day to claim the killing. The remaining force is treated as preparation for a personal encounter, making many lives absorb danger so their king can meet a weakened opponent.", hi: "सभा में लौटकर रावण उपलब्ध हर हाथी, घोड़े, वाहन और योद्धा को युद्ध में भेजता है। आदेश है कि राम को घेरकर घायल किया जाए, ताकि अगले दिन रावण आकर वध अपने नाम करे। बची सेना निजी द्वंद्व की तैयारी बनती है और अनेक जीवन खतरा उठाते हैं जिससे राजा कमजोर विरोधी का सामना करे।" }, "Show thousands of individual departure lights feeding one promised duel, making the transfer of risk legible.", ["ravana", "lanka-fighters", "war-elephants", "war-horses", "rama"]),
    beat("the-field-becomes-a-river-of-loss", { en: "The field becomes a river of loss", hi: "मैदान हानि की नदी बन जाता है" }, { en: "The armies meet with arrows, clubs, trees, stones, vehicles, animals, and bodies all mixed into a violent landscape. Allied fighters tear equipment and press in groups, while Lanka's fighters answer with heavy weapons. Neither formation remains an abstract coloured mass; wounded people, fallen animals, broken mobility, and blocked routes reshape what each side can still do.", hi: "सेनाएँ बाण, गदा, वृक्ष, पत्थर, वाहन, पशु और शरीर से बने हिंसक भू-दृश्य में भिड़ती हैं। मित्र-योद्धा उपकरण तोड़कर समूहों में दबाव बनाते हैं और लंका के योद्धा भारी शस्त्रों से उत्तर देते हैं। कोई दल केवल रंगीन भीड़ नहीं रहता; घायल लोग, गिरे पशु, टूटी गतिशीलता और बंद रास्ते अगली क्षमता बदलते हैं।" }, "Let casualties, damaged vehicles, and blocked paths persist as terrain changes instead of vanishing after each impact.", ["allied-fighters", "lanka-fighters", "war-elephants", "war-horses", "battlefield"]),
    beat("the-allies-fall-back-to-rama", { en: "The allies fall back to Rama", hi: "मित्र-दल राम की ओर लौटता है" }, { en: "Under sustained pressure, the allied ranks retreat toward Rama as a place of protection rather than pretending endless courage. Rama enters the opposing formation with speed that prevents fighters from tracking his position. Their inability to locate one moving attacker becomes the decisive vulnerability, while the retreat behind him remains a coordinated survival action rather than shame.", hi: "लगातार दबाव में मित्र-पंक्तियाँ असीम साहस का दिखावा करने के बजाय सुरक्षा के लिए राम की ओर लौटती हैं। राम ऐसी गति से विरोधी गठन में प्रवेश करते हैं कि योद्धा उनका स्थान नहीं पकड़ पाते। एक गतिशील आक्रमणकारी को न खोज पाना निर्णायक कमजोरी बनता है और उनके पीछे लौटना अपमान नहीं, संगठित जीवन-रक्षा रहता है।" }, "Turn the fallback into a clear protective formation, then make Rama's position uncertain without making the whole field unreadable.", ["rama", "allied-fighters", "sugriva", "vibhishana", "hanuman"]),
    beat("distorted-sight-turns-fighters-on-each-other", { en: "Distorted sight turns fighters on each other", hi: "बिगड़ी दृष्टि योद्धाओं को एक-दूसरे पर मोड़ती है" }, { en: "Rama's Gandharva weapon multiplies and conceals his appearance until Lanka's fighters misidentify one another as the attacker. They strike their own ranks while seeing many Ramas, one Rama, or only the moving arc of a bow. The survivors abandon ruined vehicles and flee to Lanka, carrying the consequence of perception manipulated inside mass combat.", hi: "राम का गांधर्व अस्त्र उनकी छवि को गुणा और छिपाता है, जिससे लंका के योद्धा एक-दूसरे को आक्रमणकारी समझ लेते हैं। वे कभी अनेक राम, कभी एक राम और कभी केवल चलते धनुष की चमक देखकर अपनी ही पंक्तियों पर प्रहार करते हैं। बचे लोग टूटे वाहन छोड़कर लंका भागते और सामूहिक युद्ध में बदली अनुभूति का परिणाम साथ ले जाते हैं।" }, "Split identity markers progressively until friendly-fire paths appear, then restore clear survivor routes toward Lanka.", ["rama", "gandharva-weapon", "lanka-fighters", "lanka-survivors", "lanka-gates"]),
  ]),
  scene("lankas-women-name-the-causal-chain", ["lanka-widows", "lanka-mothers", "lanka-families", "ravana", "surpanakha", "sita", "vibhishana", "lanka-homes", "remembered-dandaka", "causal-chain"], { en: "Bereaved women connect household deaths to a sequence of choices that the court repeatedly refused to reverse.", hi: "शोकाकुल स्त्रियाँ घरों की मृत्यु को उन निर्णयों की कड़ी से जोड़ती हैं जिन्हें सभा ने बार-बार पलटने से इनकार किया।" }, [
    beat("every-house-has-a-name-to-cry", { en: "Every house has a name to cry", hi: "हर घर के पास रोने के लिए एक नाम है" }, { en: "Widows, mothers, sisters, and relatives gather around the remaining defenders and cry for husbands, sons, brothers, and kin. The losses are heard house by house rather than compressed into the size of a defeated force. Their grief makes clear that commanders' decisions travel into kitchens, sleeping rooms, caregiving networks, and futures that will continue after the battlefield falls silent.", hi: "विधवाएँ, माताएँ, बहनें और संबंधी बचे रक्षकों के पास पति, पुत्र, भाई और कुटुंब के लिए रोते हैं। हानियाँ हारी सेना की संख्या में सिमटने के बजाय घर-घर सुनाई देती हैं। उनका शोक दिखाता है कि सेनानायकों के निर्णय रसोई, सोने के कमरे, देखभाल के संबंध और उन भविष्य तक जाते हैं जो युद्ध शांत होने के बाद भी रहेंगे।" }, "Replace the casualty total with distinct household lights and relationship lines extinguished or left incomplete.", ["lanka-widows", "lanka-mothers", "lanka-families", "lanka-fighters", "lanka-homes"]),
    beat("the-past-is-reassembled-as-evidence", { en: "The past is reassembled as evidence", hi: "अतीत प्रमाण की तरह फिर जुड़ता है" }, { en: "The women recall Surpanakha's encounter, the deaths at Janasthana, Sita's abduction, Hanuman's arrival, Vali's fall, and the alliance with Sugriva. They are not merely blaming one woman for desiring Rama; they build a chain of warnings that should have changed Ravana's assessment. Memory becomes a public record of avoidable escalation.", hi: "स्त्रियाँ शूर्पणखा की भेंट, जनस्थान की मृत्यु, सीता का अपहरण, हनुमान का आगमन, वाली का पतन और सुग्रीव से गठबंधन याद करती हैं। वे केवल एक स्त्री की इच्छा पर दोष नहीं डालतीं; वे चेतावनियों की ऐसी कड़ी बनाती हैं जिसे रावण का आकलन बदलना चाहिए था। स्मृति टाले जा सकने वाले विस्तार का सार्वजनिक लेखा बनती है।" }, "Reconnect earlier locations as a chronological evidence path leading into present-day Lanka rather than as decorative flashbacks.", ["surpanakha", "sita", "hanuman", "vali", "sugriva", "remembered-dandaka"]),
    beat("ignored-counsel-sits-inside-the-chain", { en: "Ignored counsel sits inside the chain", hi: "अनसुना परामर्श कड़ी के भीतर बैठता है" }, { en: "Vibhishana's advice appears in their account as a practical chance to protect Lanka, not as proof that residents deserved what followed. They recognise that returning Sita could have interrupted the chain even after earlier harms. Ravana's refusal therefore remains a governing choice, while responsibility is not transferred onto families who lacked power to make it.", hi: "विभीषण की सलाह उनके वृत्तांत में लंका बचाने का व्यावहारिक अवसर बनती है, यह प्रमाण नहीं कि निवासियों ने बाद की हानि कमाई थी। वे समझती हैं कि पिछली हिंसा के बाद भी सीता की वापसी कड़ी रोक सकती थी। रावण का इनकार इसलिए शासन का निर्णय रहता है और जिम्मेदारी उन परिवारों पर नहीं जाती जिनके पास निर्णय का अधिकार नहीं था।" }, "Place the ignored return-Sita branch at several points in the causal chain while keeping civilian agency limits visible.", ["vibhishana", "ravana", "sita", "lanka-families", "return-sita-path"]),
    beat("grief-becomes-political-understanding", { en: "Grief becomes political understanding", hi: "शोक राजनीतिक समझ बनता है" }, { en: "The women conclude that Ravana's protections did not include the human opponent he dismissed, and that repeated battlefield losses still failed to produce correction. Their diagnosis does not erase fear of Rama's power or the pain caused by his army. It shows ordinary residents reasoning about leadership, consequence, and refuge while the ruler continues toward another attack.", hi: "स्त्रियाँ समझती हैं कि रावण के वरदान में वह मनुष्य शामिल नहीं था जिसे उसने तुच्छ जाना और लगातार युद्ध-हानियाँ भी सुधार नहीं ला सकीं। उनका निष्कर्ष राम की शक्ति का भय या उनकी सेना से हुई पीड़ा नहीं मिटाता। वह सामान्य निवासियों को नेतृत्व, परिणाम और शरण पर विचार करते दिखाता है, जबकि राजा अगले आक्रमण की ओर बढ़ता है।" }, "Let household voices illuminate the governance map while Ravana's isolated route continues away from them toward battle.", ["lanka-widows", "lanka-mothers", "ravana", "rama", "lanka"]),
  ]),
  scene("ravana-marches-past-every-warning", ["ravana", "mahodara", "mahaparsha", "virupaksha", "lanka-fighters", "lanka-families", "war-chariot", "bad-omens", "lanka-gate", "allied-fighters"], { en: "Ravana answers grief with another mobilisation and ignores every signal that might have interrupted it.", hi: "रावण शोक का उत्तर नई लामबंदी से देता है और उसे रोक सकने वाले हर संकेत को अनदेखा करता है।" }, [
    beat("grief-is-converted-into-an-order", { en: "Grief is converted into an order", hi: "शोक आदेश में बदल दिया जाता है" }, { en: "Hearing lamentation across Lanka, Ravana summons Mahodara, Mahaparsha, and Virupaksha and orders the remaining fighters prepared. He promises to repair the loss of sons, brothers, and commanders by killing Rama, Lakshmana, and the allied ranks. Mourning becomes fuel for repetition rather than information capable of changing policy.", hi: "पूरी लंका का विलाप सुनकर रावण महोदर, महापार्श्व और विरूपाक्ष को बुलाकर बचे योद्धा तैयार करवाता है। वह पुत्रों, भाइयों और सेनानायकों की हानि राम, लक्ष्मण और मित्र-दल को मारकर भरने का वचन देता है। शोक नीति बदलने वाली सूचना के बजाय दोहराव का ईंधन बन जाता है।" }, "Route the sound of homes into the court, then show Ravana redirecting it outward as military command.", ["ravana", "mahodara", "mahaparsha", "virupaksha", "lanka-families"]),
    beat("soldiers-leave-every-house", { en: "Soldiers leave every house", hi: "सैनिक हर घर से निकलते हैं" }, { en: "Commanders move through Lanka calling fighters from their homes with many kinds of equipment. Vehicles, animals, infantry, armour, standards, and a weapon-filled royal car assemble around Ravana. The scale is impressive, but every outward path begins at a residence already hearing bereavement, so mobilisation enlarges the number of families exposed to another absence.", hi: "सेनानायक लंका के घरों में घूमकर अनेक प्रकार के उपकरणों के साथ योद्धाओं को बुलाते हैं। वाहन, पशु, पैदल दल, कवच, ध्वज और अस्त्रों से भरा राजरथ रावण के चारों ओर जुटते हैं। पैमाना विशाल है, पर हर बाहर जाती राह ऐसे घर से शुरू होती है जहाँ पहले ही शोक सुनाई दे रहा है; लामबंदी नए परिवारों को अनुपस्थिति के खतरे में डालती है।" }, "Animate departure paths from individual homes into formations, preserving the homes after their fighters leave.", ["lanka-fighters", "lanka-families", "war-chariot", "war-animals", "ravana"]),
    beat("the-procession-reads-itself-as-certain", { en: "The procession reads itself as certain", hi: "जुलूस स्वयं को निश्चित विजय मानता है" }, { en: "Ravana enters the radiant car beneath ceremonial sound, umbrellas, standards, and claims of unmatched conquest. The display restores confidence among followers and terrifies some allied fighters before weapons meet. Public spectacle therefore performs certainty at the very moment the city has the strongest accumulated evidence that certainty has repeatedly failed.", hi: "रावण वाद्य, छत्र, ध्वज और अतुल विजय के दावों के बीच चमकते रथ पर चढ़ता है। यह प्रदर्शन अनुयायियों में भरोसा लौटाता और अस्त्र मिलने से पहले कुछ मित्र-योद्धाओं को डराता है। सार्वजनिक वैभव उसी क्षण निश्चितता का अभिनय करता है जब नगर के पास उसके बार-बार विफल होने के सबसे अधिक प्रमाण हैं।" }, "Contrast the polished procession layer with the dim household-loss layer still visible behind Lanka's gate.", ["ravana", "lanka-fighters", "allied-fighters", "royal-procession", "lanka-gate"]),
    beat("warnings-are-seen-and-overridden", { en: "Warnings are seen and overridden", hi: "चेतावनियाँ देखकर भी दबाई जाती हैं" }, { en: "Light changes, animals cry, the earth shakes, Ravana's body trembles, and the vehicle slows, yet the march continues. These signs belong to the account's world and function as repeated chances to pause, not as a modern forecasting system. Ravana's decisive action is not failing to notice them; it is subordinating every warning to the demand for retaliation.", hi: "प्रकाश बदलता, पशु पुकारते, धरती काँपती, रावण का शरीर फड़कता और वाहन धीमा होता है, फिर भी यात्रा जारी रहती है। ये संकेत इस आख्यान के जगत में रुकने के बार-बार अवसर हैं, आज की भविष्यवाणी प्रणाली नहीं। रावण की निर्णायक भूल उन्हें न देखना नहीं, हर चेतावनी को प्रतिशोध की माँग के नीचे रखना है।" }, "Surface each warning as a pause opportunity that Ravana actively crosses, avoiding decorative superstition effects.", ["ravana", "bad-omens", "war-chariot", "lanka-fighters", "battlefield"]),
  ]),
  scene("three-commanders-carry-the-last-defence", ["sugriva", "angada", "jambavan", "gavaksha", "virupaksha", "mahodara", "mahaparsha", "ravana", "allied-fighters", "lanka-fighters", "shrinking-armies"], { en: "Three close contests remove Ravana's remaining commanders while exposing exhaustion, support, and equipment as part of every result.", hi: "तीन निकट संघर्ष रावण के बचे सेनानायकों को हटाते हैं और हर परिणाम में थकान, सहारा तथा उपकरण की भूमिका खोलते हैं।" }, [
    beat("virupaksha-restores-a-failing-line", { en: "Virupaksha restores a failing line", hi: "विरूपाक्ष टूटती पंक्ति संभालता है" }, { en: "As Ravana's arrows scatter allied fighters, Sugriva places Sushena over a formation and enters with supporting leaders. Virupaksha leaves his vehicle for an elephant, steadies Lanka's frightened ranks, and wounds Sugriva into temporary unconsciousness. The contest changes through command handoff, mount choice, recovery time, and a close opening rather than raw strength alone.", hi: "रावण के बाण मित्र-योद्धाओं को बिखेरते हैं तो सुग्रीव एक पंक्ति सुषेण को सौंपकर सहायक नेताओं के साथ उतरते हैं। विरूपाक्ष रथ छोड़ हाथी पर चढ़ता, डरी लंका-पंक्तियाँ संभालता और सुग्रीव को कुछ समय के लिए अचेत करता है। संघर्ष केवल बल से नहीं, कमान सौंपने, वाहन चुनने, उठने के समय और निकट अवसर से बदलता है।" }, "Track command ownership and mount changes as functional state, keeping both armies' recovery windows visible.", ["sugriva", "sushena", "virupaksha", "war-elephant", "allied-fighters", "lanka-fighters"]),
    beat("one-opening-ends-virupakshas-fight", { en: "One opening ends Virupaksha's fight", hi: "एक अवसर विरूपाक्ष का युद्ध समाप्त करता है" }, { en: "After blade, armour, fists, falls, and returns, Sugriva waits for one usable opening and strikes Virupaksha down. Lanka's fighters see a commander who had restored their courage collapse, while allied ranks regain movement. Victory arises from persistence after injury and timing, but the fallen man's distress is not turned into a comic or disposable animation.", hi: "खड्ग, कवच, घूँसे, गिरने और फिर उठने के बाद सुग्रीव एक उपयोगी अवसर की प्रतीक्षा कर विरूपाक्ष को गिराते हैं। लंका के योद्धा साहस लौटाने वाले सेनानायक को ढहते देखते और मित्र-पंक्तियाँ फिर चलती हैं। विजय चोट के बाद टिके रहने और समय से आती है, पर गिरे व्यक्ति की पीड़ा हास्यास्पद या फेंक देने योग्य दृश्य नहीं बनती।" }, "Slow the final opening enough to show perception and fatigue, then let both formations react to a named command loss.", ["sugriva", "virupaksha", "allied-fighters", "lanka-fighters", "shrinking-armies"]),
    beat("mahodara-and-sugriva-exhaust-every-tool", { en: "Mahodara and Sugriva exhaust every tool", hi: "महोदर और सुग्रीव हर साधन थका देते हैं" }, { en: "Ravana tells Mahodara that the remaining hope rests on him, and Mahodara enters a force already reduced by repeated fighting. He and Sugriva break stones, trees, mounts, clubs, iron weapons, armour, and balance before reaching blades at close range. The final strike comes only after both are exhausted and Mahodara's weapon catches in Sugriva's protection.", hi: "रावण महोदर से कहता है कि बची आशा उसी पर है और वह लगातार युद्ध से घट चुके दल में उतरता है। वह और सुग्रीव पत्थर, वृक्ष, वाहन, गदा, लोहे के शस्त्र, कवच तथा संतुलन तोड़ते हुए निकट खड्ग-युद्ध तक पहुँचते हैं। अंतिम प्रहार दोनों के थकने और महोदर का शस्त्र सुग्रीव की सुरक्षा में अटकने के बाद आता है।" }, "Let discarded tools remain around the duel as a visible history of adaptation and accumulated fatigue.", ["ravana", "mahodara", "sugriva", "allied-fighters", "lanka-fighters", "broken-weapons"]),
    beat("angada-does-not-fight-alone", { en: "Angada does not fight alone", hi: "अंगद अकेले नहीं लड़ते" }, { en: "Mahaparsha attacks Angada's formation after Mahodara falls, and his arrows wound Jambavan, Gavaksha, and many others. Jambavan destroys the vehicle and horses, while Angada removes the bow and finally breaks Mahaparsha's chest. Support changes the opponent's mobility before Angada's decisive blow, making the result collective even though one fighter lands the end.", hi: "महोदर के गिरने पर महापार्श्व अंगद की पंक्ति पर आक्रमण करता और उसके बाण जाम्बवान, गवाक्ष तथा अनेक साथियों को घायल करते हैं। जाम्बवान वाहन और घोड़े नष्ट करते, अंगद धनुष हटाकर अंत में महापार्श्व का वक्ष तोड़ते हैं। अंगद के निर्णायक प्रहार से पहले सहारा विरोधी की गतिशीलता बदलता है, इसलिए अंत एक योद्धा के हाथ से होकर भी सामूहिक रहता है।" }, "Keep Jambavan and Gavaksha connected to the outcome so Angada's final action does not erase supporting labour or wounds.", ["angada", "mahaparsha", "jambavan", "gavaksha", "allied-fighters", "lanka-fighters"]),
  ]),
  scene("rama-and-ravana-enter-the-same-field", ["rama", "ravana", "lakshmana", "allied-fighters", "lanka-fighters", "ravanas-charioteer", "war-chariot", "weapon-counters", "battlefield", "moving-fronts"], { en: "Ravana reaches Rama after cutting through the wider ranks, and their first direct exchange establishes a mobile, adaptive contest.", hi: "रावण विस्तृत पंक्तियाँ काटकर राम तक पहुँचता है और उनका पहला सीधा संघर्ष गतिशील, बदलता द्वंद्व स्थापित करता है।" }, [
    beat("ravana-enters-through-the-wider-army", { en: "Ravana enters through the wider army", hi: "रावण बड़ी सेना के बीच से प्रवेश करता है" }, { en: "With his commanders dead, Ravana tells the charioteer that killing Rama and Lakshmana will answer every loss. He does not travel through an empty corridor: his weapon darkens the field, wounds allied fighters, and forces groups to scatter before Rama advances to stop him. The main duel is therefore reached through consequences borne by many unnamed people.", hi: "सेनानायकों की मृत्यु के बाद रावण सारथी से कहता है कि राम-लक्ष्मण का वध हर हानि का उत्तर होगा। वह खाली रास्ते से नहीं आता; उसका अस्त्र मैदान अँधेरा करता, मित्र-योद्धाओं को घायल करता और समूहों को बिखेरता है, तब राम उसे रोकने बढ़ते हैं। मुख्य द्वंद्व तक पहुँचने का भार अनेक अनाम लोग उठाते हैं।" }, "Open the boss route through damaged allied formations, preserving every displaced group as part of the field.", ["ravana", "ravanas-charioteer", "allied-fighters", "rama", "lakshmana"]),
    beat("lakshmana-tests-the-approach", { en: "Lakshmana tests the approach", hi: "लक्ष्मण आगे बढ़कर परखते हैं" }, { en: "Lakshmana attempts the first interception, but Ravana reads and cuts his volleys with efficient counters. Ravana then turns to Rama rather than spending the entire encounter on the younger brother. Lakshmana's failed interception still provides information about timing and skill, so it remains part of the shared effort instead of disappearing as an irrelevant prelude.", hi: "लक्ष्मण पहला अवरोध बनते हैं, पर रावण उनके बाणों को पढ़कर कुशल उत्तर से काट देता है। वह पूरा संघर्ष छोटे भाई पर लगाने के बजाय राम की ओर मुड़ता है। लक्ष्मण का असफल अवरोध भी समय और कौशल की सूचना देता है, इसलिए निरर्थक प्रस्तावना बनकर मिटने के बजाय सामूहिक प्रयास का हिस्सा रहता है।" }, "Visualize the interception as a brief measurement exchange whose learned timing carries into Rama's next position.", ["lakshmana", "ravana", "rama", "weapon-counters", "battlefield"]),
    beat("two-moving-centres-take-shape", { en: "Two moving centres take shape", hi: "दो गतिशील केंद्र बनते हैं" }, { en: "Rama and Ravana circle, cross, and exchange arrows that cut one another in the air while their positions constantly shift. Their weapons turn the sky into contested space and the ground into changing cover. The encounter should feel like navigating two dangerous moving systems, not watching fixed portraits trade larger flashes from opposite sides.", hi: "राम और रावण घूमते, एक-दूसरे को पार करते और ऐसे बाण चलाते हैं जो आकाश में परस्पर कटते हैं; उनकी स्थिति लगातार बदलती है। अस्त्र आकाश को विवादित क्षेत्र और भूमि को बदलती आड़ बनाते हैं। संघर्ष स्थिर चित्रों द्वारा बड़ी चमक फेंकने के बजाय दो खतरनाक गतिशील प्रणालियों की यात्रा जैसा लगता है।" }, "Use crossing trajectories, temporary safe pockets, and shifting cover so spatial reading matters throughout the exchange.", ["rama", "ravana", "war-chariot", "weapon-counters", "moving-fronts"]),
    beat("weapons-change-form-and-answer", { en: "Weapons change form and answer", hi: "अस्त्र रूप बदलकर उत्तर पाते हैं" }, { en: "Ravana sends forms associated with predatory animals, serpents, and other threats; Rama answers with fire and other fitting counters. Effects collide and disappear rather than accumulating as meaningless spectacle, though some spillover still strikes allied fighters. Each response solves a particular danger while leaving the wider human cost and the opponent's next option in view.", hi: "रावण शिकारी पशुओं, सर्पों और अन्य खतरों से जुड़े रूप भेजता है; राम अग्नि और उपयुक्त प्रतिअस्त्रों से उत्तर देते हैं। प्रभाव निरर्थक चमक की परत बनने के बजाय टकराकर मिटते हैं, फिर भी कुछ फैलाव मित्र-योद्धाओं को लगता है। हर उत्तर विशेष खतरा सुलझाता है और व्यापक मानवीय कीमत तथा विरोधी का अगला विकल्प दृश्य रखता है।" }, "Make every counter alter one active threat and clear the screen, while persistent injuries remain outside the effect layer.", ["rama", "ravana", "weapon-counters", "allied-fighters", "battlefield"]),
  ]),
  scene("lakshmana-shields-vibhishana-and-falls", ["lakshmana", "vibhishana", "ravana", "rama", "hanuman", "sugriva", "allied-fighters", "ravanas-chariot", "maya-dart", "care-circle"], { en: "Lakshmana protects Vibhishana from Ravana's retaliation and is struck down, forcing the duel to reorganise around care.", hi: "लक्ष्मण रावण के प्रतिशोध से विभीषण को बचाकर गिरते हैं और द्वंद्व को देखभाल के चारों ओर फिर संगठित होना पड़ता है।" }, [
    beat("the-chariot-is-dismantled-by-several-hands", { en: "The chariot is dismantled by several hands", hi: "कई हाथ रथ को तोड़ते हैं" }, { en: "Lakshmana cuts Ravana's standard, bow, and charioteer, while Vibhishana kills the horses. Their combined attack removes mobility and command support, forcing Ravana to the ground. The success immediately creates danger for Vibhishana because his visible contribution turns the conflict into an enraged brother's attempt at retaliation.", hi: "लक्ष्मण रावण का ध्वज, धनुष और सारथी काटते हैं, जबकि विभीषण घोड़े मारते हैं। उनका संयुक्त आक्रमण गतिशीलता और कमान का सहारा हटाकर रावण को भूमि पर लाता है। यही सफलता विभीषण के लिए तत्काल खतरा बनती है, क्योंकि उनका स्पष्ट योगदान युद्ध को क्रोधित भाई के प्रतिशोध में बदल देता है।" }, "Show the vehicle losing distinct functions to two collaborators, then redirect Ravana's attention along the family bond.", ["lakshmana", "vibhishana", "ravana", "ravanas-chariot", "ravanas-charioteer"]),
    beat("lakshmana-enters-the-darts-path", { en: "Lakshmana enters the dart's path", hi: "लक्ष्मण शक्ति के मार्ग में आते हैं" }, { en: "Ravana throws a dart at Vibhishana, and Lakshmana cuts it before stepping between them as another weapon is raised. Protection here is a physical placement that accepts danger, not a general promise spoken from safety. It also honours Vibhishana's earlier risks without treating kinship with Ravana as a reason he should face retaliation alone.", hi: "रावण विभीषण पर शक्ति फेंकता है और लक्ष्मण उसे काटकर अगला अस्त्र उठते समय दोनों के बीच आ जाते हैं। यहाँ रक्षा सुरक्षित स्थान से बोला सामान्य वचन नहीं, खतरा स्वीकार करने वाली शारीरिक स्थिति है। यह विभीषण के पहले जोखिमों का सम्मान भी करती है और रावण से रक्त-संबंध को अकेले प्रतिशोध झेलने का कारण नहीं मानती।" }, "Place Lakshmana's body as a clear protective line between brothers, making the accepted risk spatially legible.", ["lakshmana", "vibhishana", "ravana", "protective-line", "maya-dart"]),
    beat("ramas-wish-cannot-stop-the-impact", { en: "Rama's wish cannot stop the impact", hi: "राम की कामना प्रहार नहीं रोक पाती" }, { en: "Ravana redirects the irresistible dart toward Lakshmana. Rama calls for its force to fail, yet it pierces Lakshmana's chest and pins him to the earth. The moment refuses an effortless rescue: love and exceptional capacity do not erase injury, and the field must respond to a body requiring immediate extraction and protection.", hi: "रावण अजेय शक्ति लक्ष्मण की ओर मोड़ता है। राम उसकी ऊर्जा विफल होने की कामना करते हैं, फिर भी वह लक्ष्मण का वक्ष भेदकर उन्हें धरती से बाँध देती है। क्षण सरल चमत्कारी बचाव से इनकार करता है; प्रेम और असाधारण क्षमता चोट नहीं मिटाते, अब मैदान को तत्काल निकालने और सुरक्षा चाहने वाले शरीर के अनुसार बदलना पड़ता है।" }, "Drive the impact into the terrain and force every nearby route to reconfigure around a grounded wounded person.", ["ravana", "lakshmana", "rama", "maya-dart", "allied-fighters"]),
    beat("battle-and-care-must-happen-together", { en: "Battle and care must happen together", hi: "युद्ध और देखभाल साथ चलने चाहिए" }, { en: "Allied fighters cannot remove the dart while Ravana keeps firing. Rama breaks it under attack, embraces Lakshmana, then asks Hanuman and Sugriva to hold a protective circle while he pushes Ravana back. The response divides labour between defence, extraction, emotional connection, and continued combat instead of making one hero perform every necessary action alone.", hi: "रावण की निरंतर वर्षा में मित्र-योद्धा शक्ति नहीं निकाल पाते। राम प्रहार सहते हुए उसे तोड़ते, लक्ष्मण को गले लगाते और हनुमान-सुग्रीव से सुरक्षा-वृत्त थामने को कहते हैं, जबकि वे रावण को पीछे धकेलते हैं। उत्तर रक्षा, निष्कर्षण, भावनात्मक संबंध और जारी युद्ध में काम बाँटता है; एक नायक सब कुछ अकेले नहीं करता।" }, "Split the field into a moving combat front and a protected care circle connected by visible support routes.", ["rama", "lakshmana", "hanuman", "sugriva", "allied-fighters", "care-circle"]),
  ]),
  scene("care-brings-lakshmana-back", ["rama", "lakshmana", "sushena", "hanuman", "sugriva", "allied-caregivers", "care-circle", "medicine-mountain", "healing-herbs", "battlefield"], { en: "Diagnosis, travel, medicine, and encouragement restore Lakshmana and Rama's capacity to continue.", hi: "पहचान, यात्रा, औषधि और प्रोत्साहन लक्ष्मण तथा राम की आगे बढ़ने की क्षमता लौटाते हैं।" }, [
    beat("rama-cannot-imagine-victory-without-his-brother", { en: "Rama cannot imagine victory without his brother", hi: "राम भाई के बिना विजय नहीं सोच पाते" }, { en: "Seeing Lakshmana motionless, Rama says victory, Sita, kingdom, and even life would be empty without him. He imagines facing Sumitra, Kausalya, Bharata, Shatrughna, and the reproach of returning alone. Grief expands from the wounded body into the whole family network, revealing dependence rather than an invulnerable leader briefly losing composure.", hi: "लक्ष्मण को निश्चल देखकर राम कहते हैं कि उनके बिना विजय, सीता, राज्य और जीवन भी खाली होंगे। वे सुमित्रा, कौशल्या, भरत, शत्रुघ्न और अकेले लौटने के प्रश्न की कल्पना करते हैं। शोक घायल शरीर से पूरे परिवार-जाल में फैलता है और अजेय नेता की क्षणिक कमजोरी नहीं, वास्तविक निर्भरता खोलता है।" }, "Expand Rama's grief through connected family nodes while keeping Lakshmana's breathing body at the centre.", ["rama", "lakshmana", "sumitra", "kausalya", "bharata", "shatrughna"]),
    beat("sushena-distinguishes-injury-from-death", { en: "Sushena distinguishes injury from death", hi: "सुषेण चोट और मृत्यु का अंतर बताते हैं" }, { en: "Sushena interrupts despair with observation: Lakshmana's face has not changed like a dead person's, his body retains signs of life, and his heart still moves. This does not minimize the wound; it replaces an unverified conclusion with a care decision. Attention to visible evidence reopens action at the moment grief has made every future appear closed.", hi: "सुषेण निरीक्षण से निराशा रोकते हैं: लक्ष्मण का मुख मृत व्यक्ति की तरह नहीं बदला, शरीर में जीवन के संकेत हैं और हृदय चल रहा है। यह चोट को छोटा नहीं करता; अप्रमाणित निष्कर्ष को देखभाल के निर्णय से बदलता है। जब शोक हर भविष्य बंद दिखाता है, दृश्य प्रमाण पर ध्यान फिर कार्रवाई खोलता है।" }, "Shift the field from a presumed-death state to an urgent-treatment state through Sushena's observable signs.", ["sushena", "lakshmana", "rama", "allied-caregivers", "care-circle"]),
    beat("hanuman-carries-the-summit-again", { en: "Hanuman carries the summit again", hi: "हनुमान फिर शिखर उठा लाते हैं" }, { en: "Sushena gives Hanuman an exact route and names the needed medicines. Unable to distinguish them quickly, Hanuman chooses the reversible certainty of carrying the whole summit rather than gambling with the wrong plant or losing time. The feat is spectacular, but its purpose is logistical care governed by uncertainty, distance, and a wounded person's shrinking window.", hi: "सुषेण हनुमान को सटीक मार्ग और आवश्यक औषधियों के नाम देते हैं। उन्हें शीघ्र अलग न पहचान पाने पर हनुमान गलत पौधे का जोखिम या समय खोने के बजाय पूरा शिखर लाने की सुनिश्चित राह चुनते हैं। अद्भुत कार्य का उद्देश्य अनिश्चितता, दूरी और घायल व्यक्ति के घटते समय से संचालित देखभाल है।" }, "Make the mountain flight a time-critical supply route whose destination remains the care circle, not a detached spectacle.", ["hanuman", "sushena", "lakshmana", "medicine-mountain", "healing-herbs"]),
    beat("recovery-restores-a-shared-promise", { en: "Recovery restores a shared promise", hi: "स्वास्थ्य साझा वचन लौटाता है" }, { en: "Sushena prepares the medicine, Lakshmana rises, and the surrounding fighters celebrate before Rama embraces him. Lakshmana then challenges Rama's despair and asks him to fulfil the promise to end the conflict before sunset. Recovery does not make either brother invulnerable; it returns mutual responsibility, affection, and purpose after both have depended on others.", hi: "सुषेण औषधि तैयार करते, लक्ष्मण उठते और आसपास के योद्धा हर्ष करते हैं; फिर राम उन्हें गले लगाते हैं। लक्ष्मण राम की निराशा को चुनौती देकर सूर्यास्त से पहले संघर्ष समाप्त करने का वचन निभाने को कहते हैं। स्वास्थ्य किसी भाई को अजेय नहीं बनाता; दूसरों पर निर्भर होने के बाद परस्पर जिम्मेदारी, स्नेह और उद्देश्य लौटाता है।" }, "Close on an embrace inside the full care team, then reopen the battle route as a shared commitment rather than solitary rage.", ["sushena", "lakshmana", "rama", "hanuman", "allied-caregivers", "allied-fighters"]),
  ]),
  scene("matali-makes-the-ground-equal", ["rama", "ravana", "matali", "indra", "vibhishana", "allied-fighters", "celestial-horses", "indras-chariot", "serpent-weapon", "garuda-counter"], { en: "Matali's arrival removes the unequal footing between a fighter on the ground and a moving war car, but not the danger of the encounter.", hi: "मातलि का आगमन पैदल योद्धा और चलते युद्ध-रथ की असमानता हटाता है, पर संघर्ष का खतरा नहीं।" }, [
    beat("the-field-notices-unequal-footing", { en: "The field notices unequal footing", hi: "मैदान असमान आधार देखता है" }, { en: "Rama resumes fighting from the ground while Ravana attacks from another chariot. Witnesses explicitly notice that the celebrated contest is structurally uneven, despite Rama's skill. The imbalance affects reach, speed, cover, and endurance, so correcting it is not an ornamental gift but a change in the conditions under which either fighter can act.", hi: "राम भूमि से फिर लड़ते हैं जबकि रावण दूसरे रथ से आक्रमण करता है। दर्शक स्पष्ट देखते हैं कि राम के कौशल के बावजूद प्रसिद्ध द्वंद्व संरचनात्मक रूप से असमान है। यह असमानता पहुँच, गति, आड़ और सहनशक्ति बदलती है; उसे सुधारना सजावटी उपहार नहीं, दोनों की कार्रवाई की शर्तों में परिवर्तन है।" }, "Display reach, mobility, cover, and fatigue differences between ground and chariot before relief arrives.", ["rama", "ravana", "allied-fighters", "lanka-fighters", "unequal-footing"]),
    beat("indra-sends-a-charioteer-not-an-empty-vehicle", { en: "Indra sends a charioteer, not an empty vehicle", hi: "इंद्र केवल रथ नहीं, सारथी भेजते हैं" }, { en: "Indra sends Matali with a car, horses, armour, bow, arrows, and a dart, and Matali offers to drive rather than merely hand over equipment. Rama acknowledges the vehicle before mounting it. The intervention includes skilled coordination and living animals, making mobility a relationship among driver, fighter, horses, and tools rather than a magical platform.", hi: "इंद्र मातलि को रथ, घोड़े, कवच, धनुष, बाण और शक्ति के साथ भेजते हैं; मातलि केवल सामान देकर नहीं, स्वयं सारथ्य करने आते हैं। राम चढ़ने से पहले वाहन का सम्मान करते हैं। हस्तक्षेप में कुशल समन्वय और जीवित पशु हैं, इसलिए गतिशीलता जादुई मंच नहीं, सारथी, योद्धा, घोड़े और साधनों का संबंध बनती है।" }, "Introduce each component through its operator or dependency, with Matali and the horses remaining active agents.", ["indra", "matali", "rama", "indras-chariot", "celestial-horses"]),
    beat("transformed-weapons-test-the-new-team", { en: "Transformed weapons test the new team", hi: "रूप बदलते अस्त्र नई टीम को परखते हैं" }, { en: "Ravana's arrows become serpents that surround the new car, and Rama answers with the Garuda weapon. Ravana then wounds Rama, Matali, the horses, and the standard, testing the whole coordinated system rather than one body. The vehicle equalizes opportunity but creates several vulnerable relationships that must be protected while the duel continues.", hi: "रावण के बाण सर्प बनकर नए रथ को घेरते हैं और राम गरुड़ अस्त्र से उत्तर देते हैं। फिर रावण राम, मातलि, घोड़ों और ध्वज को घायल करके एक शरीर नहीं, पूरी समन्वित व्यवस्था परखता है। वाहन अवसर बराबर करता है, पर कई संवेदनशील संबंध भी बनाता है जिन्हें द्वंद्व चलते हुए सुरक्षित रखना है।" }, "Let attacks land on distinct team functions so damage changes steering, morale, protection, or visibility rather than one health bar.", ["ravana", "rama", "matali", "celestial-horses", "serpent-weapon", "garuda-counter"]),
    beat("the-largest-dart-is-met-not-ignored", { en: "The largest dart is met, not ignored", hi: "सबसे बड़ी शक्ति का सामना होता है" }, { en: "Ravana raises a weapon that burns through Rama's first volleys and declares the end near. Rama takes the javelin brought through Matali and breaks the descending force before wounding Ravana. Success depends on the newly formed team's equipment and timing, while Ravana remains dangerous enough that no one can treat this counter as the ending.", hi: "रावण ऐसी शक्ति उठाता है जो राम के पहले बाण जला देती है और वह अंत निकट बताता है। राम मातलि के साथ आई शक्ति लेकर गिरते अस्त्र को तोड़ते और रावण को घायल करते हैं। सफलता नई बनी टीम के साधन तथा समय पर निर्भर है, पर रावण इतना खतरनाक रहता है कि कोई इस उत्तर को अंत नहीं मान सकता।" }, "Stage the counter as a timed interception enabled by Matali's equipment path, then keep both cars active.", ["ravana", "rama", "matali", "indras-dart", "indras-chariot"]),
  ]),
  scene("two-charioteers-preserve-the-fight", ["rama", "ravana", "matali", "ravanas-charioteer", "ravanas-horses", "celestial-horses", "temporary-retreat", "fatigue", "battlefield", "charioteer-knowledge"], { en: "Rama and Ravana's charioteer independently protect an incapacitated opponent, revealing restraint and professional judgment inside the duel.", hi: "राम और रावण का सारथी अलग-अलग अक्षम विरोधी की रक्षा करते हैं और द्वंद्व के भीतर संयम तथा पेशेवर निर्णय खोलते हैं।" }, [
    beat("rama-stops-when-ravana-cannot-answer", { en: "Rama stops when Ravana cannot answer", hi: "रावण उत्तर न दे सके तो राम रुकते हैं" }, { en: "After Rama's pressure leaves Ravana unable to draw, aim, or respond, Rama does not keep striking the incapacitated opponent. Restraint changes the rhythm of a contest otherwise driven toward death. It does not forgive abduction or end accountability; it recognises that helplessness creates a boundary even when the broader conflict remains unresolved.", hi: "राम के दबाव से रावण धनुष खींचने, लक्ष्य करने या उत्तर देने की अवस्था में नहीं रहता तो राम प्रहार जारी नहीं रखते। संयम मृत्यु की ओर बढ़ते द्वंद्व की लय बदलता है। यह अपहरण क्षमा या जवाबदेही समाप्त नहीं करता; यह मानता है कि असहायता सीमा बनाती है, भले व्यापक संघर्ष बाकी हो।" }, "Freeze the available finishing line when Ravana loses response capacity, making Rama's withheld action visible.", ["rama", "ravana", "matali", "incapacitated-state", "battlefield"]),
    beat("the-charioteer-removes-king-and-horses", { en: "The charioteer removes king and horses", hi: "सारथी राजा और घोड़ों को पीछे ले जाता है" }, { en: "Ravana's charioteer sees the king's collapse, the horses' exhaustion, and worsening conditions, then calmly drives them away. The withdrawal protects more than the ruler: animals, vehicle, and the possibility of coherent decision all receive respite. A subordinate acts without waiting for permission because delay would destroy the very capacity he is responsible for preserving.", hi: "रावण का सारथी राजा की शिथिलता, घोड़ों की थकान और बिगड़ती स्थिति देखकर शांत ढंग से उन्हें पीछे ले जाता है। वापसी केवल शासक नहीं, पशुओं, वाहन और सोचकर निर्णय लेने की संभावना को विश्राम देती है। अधीनस्थ बिना अनुमति काम करता है, क्योंकि देर उसी क्षमता को नष्ट करती जिसे बचाना उसका दायित्व है।" }, "Move the entire chariot system into a recovery pocket and show separate fatigue states for king, driver, and horses.", ["ravana", "ravanas-charioteer", "ravanas-horses", "temporary-retreat", "fatigue"]),
    beat("ravana-mistakes-care-for-betrayal", { en: "Ravana mistakes care for betrayal", hi: "रावण देखभाल को विश्वासघात समझता है" }, { en: "On waking, Ravana accuses the charioteer of cowardice, contempt, bribery, and destroying his reputation. His fear of appearing weak makes protective withdrawal look like disloyalty. The accusation exposes a command culture in which honest assessment is dangerous precisely when exhausted leaders most need someone able to contradict their immediate demand.", hi: "होश में आकर रावण सारथी पर कायरता, अपमान, रिश्वत और प्रतिष्ठा नष्ट करने के आरोप लगाता है। कमजोर दिखने का भय रक्षक वापसी को विश्वासघात बना देता है। आरोप ऐसी कमान-संस्कृति खोलता है जिसमें थके नेता को विरोध करने वाले की सबसे अधिक जरूरत होते समय ईमानदार आकलन सबसे खतरनाक है।" }, "Turn Ravana's accusation into pressure on the recovery pocket without visually validating the betrayal claim.", ["ravana", "ravanas-charioteer", "reputation", "command-pressure", "temporary-retreat"]),
    beat("professional-judgment-is-explained", { en: "Professional judgment is explained", hi: "पेशेवर निर्णय समझाया जाता है" }, { en: "The charioteer answers that he watched fatigue, morale, omens, terrain, distance, horses, timing, approach, pause, and retreat. He frames the unwelcome decision as affection joined to expertise, not fear. Ravana accepts the explanation and orders a return, leaving a hard truth visible: skilled care preserved the fight even though the leader tried to punish it.", hi: "सारथी बताता है कि उसने थकान, मनोबल, संकेत, भूमि, दूरी, घोड़े, समय, आगे बढ़ना, रुकना और लौटना देखा। वह अप्रिय निर्णय को भय नहीं, स्नेह से जुड़ी विशेषज्ञता कहता है। रावण स्पष्टीकरण मानकर वापसी का आदेश देता है; कठोर सत्य बचता है कि नेता ने जिसे दंडित करना चाहा, उसी कुशल देखभाल ने युद्ध की क्षमता बचाई।" }, "Display the charioteer's full decision model as linked field signals, then reconnect the car only after recovery.", ["ravanas-charioteer", "ravana", "ravanas-horses", "charioteer-knowledge", "battlefield"]),
  ]),
  scene("agastya-returns-ramas-focus", ["rama", "agastya", "surya", "ravana", "matali", "witnessing-beings", "aditya-hridaya", "battlefield", "sunrise-light", "renewed-attention"], { en: "Agastya gives Rama a contemplative practice that gathers exhausted attention before the renewed encounter.", hi: "अगस्त्य राम को ऐसा चिंतन देते हैं जो नए संघर्ष से पहले थका ध्यान फिर एकत्र करता है।" }, [
    beat("agastya-enters-a-spent-moment", { en: "Agastya enters a spent moment", hi: "अगस्त्य थके हुए क्षण में आते हैं" }, { en: "Agastya approaches while Rama stands tired and thoughtful before Ravana's return. He does not deny exhaustion or replace tactical action with a promise of automatic victory. He offers a bounded contemplation addressed to the Sun, creating time for breath, orientation, and renewed intention at the threshold of another sustained encounter.", hi: "रावण की वापसी से पहले थके और चिंतन में खड़े राम के पास अगस्त्य आते हैं। वे थकान नकारते या सैन्य कार्रवाई को स्वतः विजय के वादे से नहीं बदलते। वे सूर्य को संबोधित सीमित चिंतन देते हैं, जिससे अगले लंबे संघर्ष की दहलीज पर श्वास, दिशा और नई मंशा का समय बनता है।" }, "Quiet the battlefield without erasing it, bringing Agastya into a clear pause between two active danger routes.", ["agastya", "rama", "ravana", "matali", "battlefield"]),
    beat("the-sun-is-seen-through-many-functions", { en: "The Sun is seen through many functions", hi: "सूर्य अनेक कार्यों से दिखाई देते हैं" }, { en: "The recitation names the Sun through light, time, seasons, wakefulness, rain, heat, action, creation, destruction, and many divine associations. Its density expands Rama's attention beyond the opponent directly before him. The movement is from a narrowed crisis mind toward a world that still has order, cycles, duties, and life beyond the duel.", hi: "पाठ सूर्य को प्रकाश, समय, ऋतु, जागरण, वर्षा, ताप, कर्म, सृजन, विनाश और अनेक दिव्य संबंधों से नाम देता है। उसका विस्तार राम का ध्यान सामने खड़े विरोधी से बहुत बाहर ले जाता है। गति संकट में सिमटे मन से ऐसे जगत की ओर है जहाँ द्वंद्व के पार भी क्रम, चक्र, कर्तव्य और जीवन हैं।" }, "Expand a solar constellation through time, ecology, work, and divine associations without turning names into a cluttered list.", ["rama", "surya", "aditya-hridaya", "seasons", "living-world"]),
    beat("recitation-becomes-attention-not-a-shortcut", { en: "Recitation becomes attention, not a shortcut", hi: "पाठ शॉर्टकट नहीं, एकाग्रता बनता है" }, { en: "Agastya asks Rama to concentrate, recite, and worship before acting. The value visible here is a transition from grief and anxiety into gathered readiness, not a transferable guarantee that repetition forces a desired outcome in every present-day crisis. The practice belongs to this epic moment and supports action that still requires judgment, skill, and risk.", hi: "अगस्त्य राम से कार्रवाई से पहले ध्यान, पाठ और उपासना करने को कहते हैं। यहाँ दिखाई देता मूल्य शोक और चिंता से एकत्र तैयारी की ओर परिवर्तन है, यह आज के हर संकट में इच्छित परिणाम मजबूर करने वाली सार्वभौमिक गारंटी नहीं। अभ्यास इस महाकाव्य क्षण का है और ऐसी कार्रवाई सहारा देता है जिसमें अब भी निर्णय, कौशल और जोखिम चाहिए।" }, "Show internal attention stabilizing before any external advantage appears, preserving the boundary between contemplation and guarantee.", ["agastya", "rama", "aditya-hridaya", "renewed-attention", "battlefield"]),
    beat("rama-returns-to-action-deliberately", { en: "Rama returns to action deliberately", hi: "राम सोचकर कार्रवाई में लौटते हैं" }, { en: "Rama looks toward the Sun, recites, takes water, steadies himself, and lifts the bow with renewed purpose. Agastya withdraws and the wider witnesses remain, but Rama must still meet Ravana through Matali, equipment, and his own decisions. The pause ends by restoring deliberate agency rather than replacing the coming struggle with a prewritten result.", hi: "राम सूर्य की ओर देखकर पाठ करते, जल लेते, स्वयं को स्थिर करते और नए उद्देश्य से धनुष उठाते हैं। अगस्त्य हटते और व्यापक साक्षी बने रहते हैं, पर राम को अब भी मातलि, साधनों और अपने निर्णयों के सहारे रावण का सामना करना है। विराम आने वाले संघर्ष को पहले से लिखे परिणाम से बदलने के बजाय सोच-समझकर कार्रवाई लौटाता है।" }, "Contract the solar field back into Rama's steady posture, Matali's reins, and the still-unresolved route ahead.", ["rama", "surya", "agastya", "matali", "ravana", "renewed-attention"]),
  ]),
  scene("the-final-cars-read-the-field", ["rama", "ravana", "matali", "ravanas-charioteer", "lakshmana", "allied-fighters", "lanka-fighters", "celestial-horses", "ravanas-horses", "battlefield-signs"], { en: "Both cars return under expert control, and the environment becomes information for morale, positioning, and danger.", hi: "दोनों रथ कुशल नियंत्रण में लौटते हैं और वातावरण मनोबल, स्थिति तथा खतरे की सूचना बनता है।" }, [
    beat("rama-requests-calm-positioning", { en: "Rama requests calm positioning", hi: "राम शांत स्थिति माँगते हैं" }, { en: "As Ravana's car approaches at speed, Rama asks Matali to place their vehicle directly against it with a steady heart and clear eye. He immediately says this is a reminder, not instruction to someone already worthy of Indra's reins. Command becomes collaborative: the fighter names intent while respecting the driver's independent mastery of movement.", hi: "रावण का रथ तेजी से आता है तो राम मातलि से शांत हृदय और स्पष्ट दृष्टि के साथ वाहन सीधे सामने रखने को कहते हैं। वे तुरंत बताते हैं कि यह इंद्र के सारथ्य योग्य विशेषज्ञ को शिक्षा नहीं, स्मरण है। कमान सहयोगी बनती है; योद्धा मंशा बताता है और चालक की गतिशीलता पर स्वतंत्र दक्षता का सम्मान करता है।" }, "Present the request and Matali's route choice as two linked decisions rather than one character remotely controlling another.", ["rama", "matali", "ravana", "indras-chariot", "celestial-horses"]),
    beat("matali-turns-position-into-advantage", { en: "Matali turns position into advantage", hi: "मातलि स्थिति को बढ़त बनाते हैं" }, { en: "Matali circles so Ravana is kept to a chosen side and uses wheel-raised dust to disrupt his view. Ravana answers by covering Rama with arrows, forcing patience under pressure. Spatial control, sight lines, and driver judgment now matter alongside weapons, so the encounter can be followed as movement through a dangerous field rather than a flat exchange.", hi: "मातलि घूमकर रावण को चुनी ओर रखते और पहियों की धूल से उसकी दृष्टि बिगाड़ते हैं। रावण राम पर बाण बरसाकर दबाव में धैर्य की माँग करता है। अब अस्त्रों के साथ स्थान-नियंत्रण, दृश्य-रेखाएँ और सारथी का निर्णय महत्वपूर्ण हैं; संघर्ष सपाट आदान-प्रदान नहीं, खतरनाक मैदान की गति बनता है।" }, "Use dust, right-side advantage, and sight lines as readable spatial mechanics without obscuring the whole scene.", ["matali", "rama", "ravana", "battlefield", "sight-lines"]),
    beat("lankas-signs-depress-the-fighting-line", { en: "Lanka's signs depress the fighting line", hi: "लंका के संकेत लड़ती पंक्ति को दबाते हैं" }, { en: "Darkness, violent weather, distressed animals, trembling ground, and falling debris accompany Ravana's route, and Lanka's fighters read them as defeat approaching. Whatever their cosmic meaning within the account, the immediate military effect is weakened confidence and impaired visibility. The signs act through bodies and decisions, not as decoration detached from the people experiencing them.", hi: "अंधकार, हिंसक मौसम, व्याकुल पशु, काँपती भूमि और गिरता मलबा रावण की राह के साथ चलते हैं; लंका के योद्धा उन्हें निकट हार की तरह पढ़ते हैं। आख्यान में उनका ब्रह्मांडीय अर्थ जो हो, तत्काल सैन्य प्रभाव घटता विश्वास और बिगड़ी दृष्टि है। संकेत उन्हें झेलते लोगों से अलग सजावट नहीं, शरीर और निर्णयों पर काम करते हैं।" }, "Connect every environmental sign to visibility, animal stress, hand steadiness, or morale in Lanka's formation.", ["ravana", "lanka-fighters", "ravanas-horses", "battlefield-signs", "lanka"]),
    beat("the-allied-line-reads-a-different-future", { en: "The allied line reads a different future", hi: "मित्र-पंक्ति अलग भविष्य पढ़ती है" }, { en: "Contrasting signs strengthen the allied side, and Lakshmana interprets Ravana as already close to defeat. Increased confidence can support coordinated action, but it does not remove the opponent or guarantee safety. Both formations enter the final exchange carrying different expectations, making morale another changing field state rather than a narrator's simple declaration of who wins.", hi: "विपरीत संकेत मित्र-पक्ष को मजबूत करते और लक्ष्मण रावण को पराजय के निकट मानते हैं। बढ़ा विश्वास संगठित कार्रवाई सहारा दे सकता है, पर विरोधी हटाता या सुरक्षा की गारंटी नहीं देता। दोनों दल अलग अपेक्षाओं के साथ अंतिम संघर्ष में जाते हैं; मनोबल कौन जीतेगा की सरल घोषणा नहीं, मैदान की बदलती अवस्था बनता है।" }, "Render contrasting morale without locking the outcome, leaving both cars, formations, and support routes operational.", ["lakshmana", "rama", "allied-fighters", "ravana", "lanka-fighters", "battlefield-signs"]),
  ]),
  scene("the-duel-refuses-an-easy-ending", ["rama", "ravana", "matali", "ravanas-charioteer", "allied-fighters", "lanka-fighters", "celestial-horses", "ravanas-horses", "regenerating-heads", "seven-day-duel"], { en: "The armies become witnesses as a technically complex duel defeats every apparent ending for seven days.", hi: "सेनाएँ साक्षी बनती हैं और तकनीकी रूप से जटिल द्वंद्व सात दिन तक हर दिखाई देते अंत को विफल करता है।" }, [
    beat("both-armies-stop-to-witness", { en: "Both armies stop to witness", hi: "दोनों सेनाएँ साक्षी बनने रुकती हैं" }, { en: "Allied and Lanka fighters stand with weapons raised but cease attacking one another as the two cars meet. Their astonished attention turns the broader battle into a held field whose future depends on the central exchange. Pausing does not erase their wounds or agency; it creates thousands of witnesses who will live with how the ending is reached.", hi: "मित्र और लंका के योद्धा अस्त्र उठाए रहते पर दोनों रथों के मिलने पर एक-दूसरे पर आक्रमण रोक देते हैं। उनका विस्मित ध्यान व्यापक युद्ध को थमे मैदान में बदलता है जिसका भविष्य केंद्रीय द्वंद्व पर निर्भर है। रुकना चोट या क्षमता नहीं मिटाता; यह हजारों ऐसे साक्षी बनाता है जो अंत तक पहुँचने का तरीका साथ लेकर जीएँगे।" }, "Freeze secondary attack routes while keeping breathing, wounds, fear, and allegiance visible across both formations.", ["allied-fighters", "lanka-fighters", "rama", "ravana", "battlefield"]),
    beat("drivers-horses-and-standards-shape-the-duel", { en: "Drivers, horses, and standards shape the duel", hi: "सारथी, घोड़े और ध्वज द्वंद्व बनाते हैं" }, { en: "The cars circle, advance, retreat, touch front to front, displace horses, and lose standards while both charioteers keep finding position. Ravana attacks Matali and the celestial horses; Rama attacks Ravana's mobility and markers. The duel is a coupled system of bodies, animals, signals, terrain, and equipment, not two isolated weapon dispensers.", hi: "रथ घूमते, आगे-पीछे होते, आमने-सामने छूते, घोड़ों को हटाते और ध्वज खोते हैं; दोनों सारथी नई स्थिति खोजते रहते हैं। रावण मातलि तथा दिव्य घोड़ों पर और राम उसकी गतिशीलता तथा संकेतों पर प्रहार करते हैं। द्वंद्व शरीर, पशु, संकेत, भूमि और उपकरणों की जुड़ी व्यवस्था है, दो अलग अस्त्र-यंत्र नहीं।" }, "Continuously update steering, horse position, standards, and visibility so no combatant floats outside the field system.", ["rama", "ravana", "matali", "ravanas-charioteer", "celestial-horses", "ravanas-horses"]),
    beat("every-severed-head-returns", { en: "Every severed head returns", hi: "हर कटा सिर लौट आता है" }, { en: "Rama repeatedly severs Ravana's heads, but each apparent finish is replaced by another. He pauses to question why arrows that ended earlier dangers do not end this one. The repeated failure turns a famous image into a problem of diagnosis: persistence alone cannot substitute for understanding what part of the opponent actually determines survival.", hi: "राम बार-बार रावण के सिर काटते हैं, पर हर दिखाई देता अंत नए सिर से बदल जाता है। वे रुककर पूछते हैं कि पहले संकट समाप्त करने वाले बाण यहाँ क्यों विफल हैं। प्रसिद्ध दृश्य पहचान की समस्या बनता है; केवल दोहराव यह समझने का विकल्प नहीं कि विरोधी के जीवन का निर्णायक आधार क्या है।" }, "Treat returning heads as failed hypotheses on a visible model, reducing spectacle as diagnostic urgency grows.", ["rama", "ravana", "regenerating-heads", "matali", "weapon-counters"]),
    beat("seven-days-consume-the-quick-ending", { en: "Seven days consume the quick ending", hi: "सात दिन शीघ्र अंत को निगल जाते हैं" }, { en: "The exchange continues through day and night for seven days without a stable pause. Skill, equipment, and endurance prevent collapse, but none produces resolution while the same ineffective logic repeats. Time must remain visible in changing light, fatigue, accumulated damage, and watching formations so the ending feels earned through duration rather than compressed into one triumphant shot.", hi: "संघर्ष सात दिन दिन-रात बिना स्थिर विराम चलता है। कौशल, उपकरण और सहनशक्ति पतन रोकते हैं, पर वही निष्फल तर्क दोहरते समय कोई समाधान नहीं देता। बदलता प्रकाश, थकान, जमा क्षति और देखती पंक्तियों में समय दृश्य रहना चाहिए, ताकि अंत एक विजयी प्रहार में सिमटने के बजाय अवधि से अर्जित लगे।" }, "Cycle light, fatigue, damage, and witness positions across seven days while preserving continuous spatial orientation.", ["rama", "ravana", "matali", "ravanas-charioteer", "seven-day-duel", "allied-fighters", "lanka-fighters"]),
  ]),
  scene("ravana-falls-and-the-survivors-remain", ["rama", "ravana", "matali", "sugriva", "lakshmana", "vibhishana", "angada", "lanka-survivors", "final-arrow", "retreat-to-lanka", "allied-fighters"], { en: "Matali redirects Rama from repetition to the decisive weapon; Ravana dies, and the ending preserves the frightened people who must return to Lanka.", hi: "मातलि राम को दोहराव से निर्णायक अस्त्र की ओर मोड़ते हैं; रावण मरता है और अंत उन भयभीत लोगों को बचाए रखता है जिन्हें लंका लौटना है।" }, [
    beat("matali-interrupts-repetition", { en: "Matali interrupts repetition", hi: "मातलि दोहराव रोकते हैं" }, { en: "After seven days, Matali asks why Rama continues as though the necessary response were unknown and reminds him that the described time has arrived. The charioteer contributes diagnosis again, not merely steering. Rama accepts the correction, showing that even the central fighter needs another person's attention to escape a pattern that effort alone has failed to solve.", hi: "सात दिन बाद मातलि पूछते हैं कि राम आवश्यक उत्तर जानते हुए भी क्यों दोहरा रहे हैं और याद दिलाते हैं कि वर्णित समय आ गया है। सारथी फिर केवल दिशा नहीं, पहचान देता है। राम सुधार स्वीकार करते हैं; केंद्रीय योद्धा को भी उस ढाँचे से निकलने के लिए दूसरे की दृष्टि चाहिए जिसे केवल प्रयास नहीं सुलझा पाया।" }, "Highlight Matali's intervention as a new decision branch opening after the repeated-head loop closes.", ["matali", "rama", "ravana", "seven-day-duel", "charioteer-knowledge"]),
    beat("the-final-arrow-is-prepared-deliberately", { en: "The final arrow is prepared deliberately", hi: "अंतिम बाण सोचकर तैयार होता है" }, { en: "Rama takes the weapon associated with Agastya and Brahma, prepares it carefully, and aims at Ravana's vital centre rather than repeating attacks on replaceable heads. The account gives it immense cosmic and physical force, yet the crucial change is also conceptual: target selection finally aligns with the actual condition that earlier attempts did not reach.", hi: "राम अगस्त्य और ब्रह्मा से जुड़े अस्त्र को लेकर सावधानी से तैयार करते और बदलते सिरों पर प्रहार दोहराने के बजाय रावण के जीवन-केंद्र पर लक्ष्य करते हैं। आख्यान उसे विशाल ब्रह्मांडीय तथा भौतिक शक्ति देता है, पर निर्णायक परिवर्तन वैचारिक भी है; लक्ष्य अंततः उस वास्तविक आधार से मिलता है जहाँ पहले प्रयास नहीं पहुँचे थे।" }, "Concentrate the wide cosmic field into one precise target line, avoiding a larger but less intelligible explosion.", ["rama", "ravana", "final-arrow", "matali", "agastya"]),
    beat("ravanas-death-ends-rule-not-every-life", { en: "Ravana's death ends rule, not every life", hi: "रावण की मृत्यु शासन समाप्त करती है, हर जीवन नहीं" }, { en: "The arrow pierces Ravana's chest, returns, and the king falls from the car as bow and weapons leave his hands. His death ends command and the immediate contest, but it does not make the people around him vanish. Lanka's surviving fighters are frightened, bereaved, and still capable of flight, memory, family attachment, and a future beyond their ruler.", hi: "बाण रावण का वक्ष भेदकर लौटता है और धनुष-अस्त्र हाथ से छूटते हुए राजा रथ से गिरता है। मृत्यु कमान और तत्काल द्वंद्व समाप्त करती है, पर आसपास के लोग गायब नहीं होते। लंका के बचे योद्धा भयभीत, शोकाकुल और फिर भी पलायन, स्मृति, पारिवारिक संबंध तथा शासक के पार भविष्य रखने वाले लोग हैं।" }, "Separate the fallen command node from the still-living Lanka network, keeping survivor paths open and named.", ["ravana", "rama", "lanka-survivors", "ravanas-chariot", "retreat-to-lanka"]),
    beat("victory-closes-on-relationships", { en: "Victory closes on relationships", hi: "विजय संबंधों पर समाप्त होती है" }, { en: "Allied fighters celebrate and some pursue retreating defenders, while Sugriva, Angada, Vibhishana, Lakshmana, and Matali gather around Rama. Relief belongs to a coalition formed through refuge, promise, care, travel, and repeated shared risk. The final image keeps joy beside grief and return routes, preparing for Lanka's aftermath rather than pretending one death has completed everyone's recovery.", hi: "मित्र-योद्धा हर्ष करते और कुछ लौटते रक्षकों का पीछा करते हैं, जबकि सुग्रीव, अंगद, विभीषण, लक्ष्मण और मातलि राम के पास जुटते हैं। राहत शरण, वचन, देखभाल, यात्रा और साझा जोखिम से बने गठबंधन की है। अंतिम दृश्य आनंद के साथ शोक और वापसी की राह रखता है, लंका के परिणाम की तैयारी करता है; एक मृत्यु को सबका स्वास्थ्य पूरा नहीं मानता।" }, "End with an expanding coalition circle beside visible grieving retreat routes, leading naturally into Lanka's aftermath.", ["rama", "sugriva", "angada", "vibhishana", "lakshmana", "matali", "allied-fighters", "lanka-survivors"]),
  ]),
];
